 @Test void frozenOriginalBaseValuesProduceRealFxAndReversalPreservesFacts(){billFact(1101,"CNY",100,"2.5");creditFact(1102,"MXN",200,"1");seed("insert into md_exchange_rate(country_id,from_ccy,to_ccy,rate_date,scope,rate,status,confirmed_by,confirmed_at) values(101,'CNY','MXN','2026-10-15','SETTLEMENT',9,'CONFIRMED',201,clock_timestamp())");var body=settlement(1101,1102,200,100,"0.5");String key=key();var result=ap.settle(c(),body,key);ap.settle(c(),body,key);assertThat(owner.queryForObject("select diff_amount from ap_fx_diff",BigDecimal.class)).isEqualByComparingTo("-50");var reversal=ap.reverse(c(),id(result),Map.of("version",1,"bizDate","2026-10-15","reason","wrong allocation"),key());assertThat(owner.queryForObject("select count(*) from ap_settlement",Integer.class)).isEqualTo(2);assertThat(owner.queryForObject("select sum(diff_amount) from ap_fx_diff",BigDecimal.class)).isZero();assertThat(owner.queryForObject("select used_amount from ap_credit_note",BigDecimal.class)).isZero();assertThat(owner.queryForObject("select paid_amount from ap_bill",BigDecimal.class)).isZero();assertThat(reversal).containsEntry("reversalOfId",id(result));}
 @Test void competingSettlementsLockBothFundingAndBill()throws Exception{billFact(1101,"MXN",80,"1");billFact(1102,"MXN",80,"1");creditFact(1103,"MXN",100,"1");assertThat(compete(()->ap.settle(c(),settlement(1101,1103,80,80,"1"),key()),()->ap.settle(c(),settlement(1102,1103,80,80,"1"),key()))).isEqualTo(1);assertThat(owner.queryForObject("select used_amount from ap_credit_note",BigDecimal.class)).isEqualByComparingTo("80");assertThat(owner.queryForObject("select count(*) from ap_settlement",Integer.class)).isEqualTo(1);}
 @Test void aFailedSecondLineRollsBackEarlierSettlementProjectionAndIdempotency(){billFact(1101,"MXN",80,"1");billFact(1102,"MXN",80,"1");creditFact(1103,"MXN",100,"1");String key=key();var one=((List<?>)settlement(1101,1103,80,80,"1").get("lines")).getFirst();var two=((List<?>)settlement(1102,1103,80,80,"1").get("lines")).getFirst();assertThatThrownBy(()->ap.settle(c(),Map.of("bizDate","2026-10-15","lines",List.of(one,two)),key)).isInstanceOf(ApiException.class);assertThat(owner.queryForObject("select used_amount from ap_credit_note",BigDecimal.class)).isZero();assertThat(owner.queryForObject("select sum(paid_amount) from ap_bill",BigDecimal.class)).isZero();assertThat(owner.queryForObject("select count(*) from ap_settlement",Integer.class)).isZero();assertThat(owner.queryForObject("select count(*) from sys_idempotency where key=?",Integer.class,key)).isZero();}
