 @Test void statementDetailsOnlyContainTheRequestedPeriodAndReconcileOpening(){seed("insert into ap_bill(id,country_id,entity_id,book_id,partner_type,partner_id,doc_no,bill_type,currency,amount,bill_date,due_date,status,base_currency,rate,rate_date,base_amount,valuation_status) values(1501,101,301,601,'SUPPLIER',801,'OPENING','PURCHASE','MXN',40,'2026-10-05','2026-10-05','CONFIRMED','MXN',1,'2026-10-05',40,'READY')");billFact(1502,"MXN",60,"1");creditFact(1503,"MXN",30,"1");ap.settle(c(),settlement(1502,1503,20,20,"1"),key());var r=ap.statement(c(),Map.of("bookId",601,"partnerId",801,"currency","MXN","periodStart","2026-10-10","periodEnd","2026-10-31"),key());assertThat(new BigDecimal(r.get("opening").toString())).isEqualByComparingTo("40");assertThat(new BigDecimal(r.get("increase").toString())).isEqualByComparingTo("60");assertThat(new BigDecimal(r.get("offset").toString())).isEqualByComparingTo("20");assertThat(new BigDecimal(r.get("closing").toString())).isEqualByComparingTo("80");assertThat((List<?>)r.get("details")).hasSize(2);assertThat(owner.queryForObject("select jsonb_array_length(detail_snapshot) from ap_statement",Integer.class)).isEqualTo(2);assertThat(r).containsEntry("identityOk",true);}
